export class RetryableError extends Error {}

export async function with_retry<T>(task: () => Promise<T>, attempts: number): Promise<T> {
	let last: unknown

	for (let attempt = 0; attempt < attempts; attempt += 1) {
		try {
			return await task()
		} catch (error) {
			if (!(error instanceof RetryableError)) throw error
			last = error
		}
	}

	throw last
}

