import { expect, it, vi } from 'vitest'
import { RetryableError, with_retry } from './retry'

it('retries a retryable error until the task succeeds', async () => {
	const task = vi.fn().mockRejectedValueOnce(new RetryableError()).mockResolvedValue('done')

	await expect(with_retry(task, 3)).resolves.toBe('done')
	expect(task).toHaveBeenCalledTimes(2)
})

it('rethrows a non-retryable error on the first attempt', async () => {
	const task = vi.fn().mockRejectedValue(new TypeError('bad input'))

	await expect(with_retry(task, 3)).rejects.toThrow('bad input')
	expect(task).toHaveBeenCalledOnce()
})
